package com.aktvhome.launcher.ui

internal data class HavenSettingSpec(
    val id: String,
    val name: String,
    val destination: SettingsDestination,
    val path: String,
    val description: String,
    val keywords: String = "",
    val focusTitle: String? = name,
    val subsection: String? = null,
)

private fun setting(
    id: String,
    name: String,
    destination: SettingsDestination,
    path: String,
    description: String,
    keywords: String = "",
    focusTitle: String? = name,
    subsection: String? = null,
) = HavenSettingSpec(id, name, destination, path, description, keywords, focusTitle, subsection)

